STYLE_MODE = "스타일로 브랜드 찾기"   # 질문 분류의 class_label (분류 라벨을 바꾸면 여기도 바꿀 것)
STYLE_TOP = 5        # 스타일로 찾을 때 보여줄 브랜드 수 (최대)
STYLE_MIN = 3
# "마뗑킴이랑 비슷한 브랜드"에서 브랜드명 뒤에 오는 말
BRAND_NAME_RE = re.compile(r"^\s*['\"]?(.+?)['\"]?\s*(?:이랑|랑|와|과|하고|같은|처럼|느낌|스타일|비슷)")
NOT_BRAND_WORDS = {"이", "그", "저", "이런", "그런", "저런", "어떤", "비슷한", "다른", "브랜드", "옷", "스타일", "느낌", "요즘", "제", "나"}


def ui_block(payload):
    """웹사이트용 구조화 데이터를 답변 끝 HTML 주석으로 붙인다: <!--fashion-ui {...} -->
    Dify 채팅은 sanitize 단계에서 HTML 주석을 지우므로 화면에 보이지 않는다.
    주석이 중간에 끝나지 않도록 JSON 문자열 안의 "--"를 \\u002d로 바꾼다 (JSON으로 읽으면 원래 값)."""
    text = json.dumps(dict(payload, v=1), ensure_ascii=False, separators=(",", ":")).replace("--", "-\\u002d")
    return "\n\n<!--fashion-ui " + text + " -->"



def _norm(text):
    return re.sub(r"[^0-9a-z가-힣]", "", (text or "").lower())


def _find_brands(query):
    """질문에 나온 브랜드를 등장 순서대로 찾는다. 한글명, 영문명, 도메인을 공백·대소문자 무시하고 매칭."""
    q = _norm(query)
    hits = []
    for domain, brand in BRAND_DATA["brands"].items():
        for alias in brand["aliases"]:
            pos = q.find(alias)
            if pos >= 0:
                hits.append((pos, -len(alias), domain))
    found = []
    for _, _, domain in sorted(hits):
        if domain not in found:
            found.append(domain)
    return found


def _find_styles(query):
    q = _norm(query)
    found = []
    for expr in sorted(BRAND_DATA["style_aliases"], key=len, reverse=True):
        if expr in q:
            found += [t for t in BRAND_DATA["style_aliases"][expr] if t not in found]
    return found


def _label(brand):
    return "{} ({})".format(brand["ko"], brand["en"]) if brand.get("en") else brand["ko"]


def _cell(text):
    """표 칸 안에서 깨지는 문자(|, 줄바꿈, 대괄호) 정리."""
    return re.sub(r"\s+", " ", str(text or "")).replace("|", "/").replace("[", "(").replace("]", ")").strip()


def _price(value):
    try:
        return "{:,}원".format(int(float(value)))
    except (TypeError, ValueError):
        return ""


def _product_strip(products):
    """대표 상품을 한 줄짜리 마크다운 표로 만든다. Dify 채팅은 표를 가로 스크롤 영역에 넣고
    표 안 이미지는 높이 200px 이하로 줄여 보여주므로, 상품이 옆으로 나란히 놓이고 넘치면 가로로 넘겨 볼 수 있다."""
    if not products:
        return ""
    images = ["![{}]({})".format(_cell(p["name"]), p["image"]) for p in products]
    names = ["[{}]({})".format(_cell(p["name"]), p["url"]) for p in products]
    prices = [_price(p.get("price")) or "-" for p in products]
    rows = [images, [":---:"] * len(products), names, prices]
    return "\n".join("| " + " | ".join(r) + " |" for r in rows)


def _style_rank(tags):
    """요청 태그와 브랜드 태그의 IDF 가중 코사인 순위. 요청 태그가 브랜드 태그에서 차지하는 비중이 클수록 위.
    (brand_profiles의 weight는 태그별 IDF라 브랜드마다 같은 값이므로, 브랜드별 비중은 코사인으로 본다)
    점수가 같으면 브랜드 태그 목록에서 요청 태그가 앞쪽에 있는 브랜드를 위로."""
    idf = BRAND_DATA["tag_idf"]
    qn = math.sqrt(sum(idf.get(t, 0) ** 2 for t in tags)) or 1
    out = []
    for domain, b in BRAND_DATA["brands"].items():
        shared = [t for t in tags if t in b["tags"]]
        if not shared:
            continue
        bn = math.sqrt(sum(idf.get(t, 0) ** 2 for t in b["tags"])) or 1
        score = sum(idf.get(t, 0) ** 2 for t in shared) / (qn * bn)
        pos = min(b["tags"].index(t) for t in shared)
        out.append((round(score, 3), -pos, domain, shared))
    out.sort(reverse=True)
    return out


def _closing(blocks):
    # 메시지가 표로 끝나면 Dify 채팅에서 마지막 표가 그려지지 않는 경우가 있어(2026-10-16, 5번째 브랜드 상품 줄 누락)
    # 표 뒤에 안내 문장을 한 줄 둔다
    return "\n\n---\n\n".join(blocks) + "\n\n브랜드 이름을 누르면 브랜드몰로, 상품 이름을 누르면 상품 페이지로 이동해요."


def _brand_block(rank, brand, title_suffix, detail_lines):
    parts = ["### {}. [{}]({}){}".format(rank, _label(brand), brand["url"], title_suffix), "\n".join(detail_lines)]
    strip = _product_strip(brand.get("products", []))
    if strip:
        parts.append(strip)
    return "\n\n".join(parts)


def _brand_card(rank, brand, score_label, score, tags, detail):
    """웹사이트 브랜드 캐러셀용 구조화 데이터."""
    return {"rank": rank, "ko": brand["ko"], "en": brand.get("en", ""), "url": brand["url"], "score_label": score_label,
            "score": score, "tags": tags, "detail": detail,
            "products": [{"name": p["name"], "price": _price(p.get("price")), "image": p["image"], "url": p["url"]}
                         for p in brand.get("products", [])]}


def _style_answer(query):
    """(마크다운, 웹사이트용 데이터 또는 None)"""
    tags = _find_styles(query)
    if not tags:
        names = ", ".join(sorted(BRAND_DATA["tag_idf"], key=lambda t: BRAND_DATA["tag_idf"][t]))
        return "어떤 스타일을 좋아하시는지 조금 더 알려주세요. 예: 빈티지, 페미닌, 스트릿, 미니멀\n\n지금 찾을 수 있는 스타일: " + names, None
    ranked = _style_rank(tags)
    if not ranked:
        return "{} 스타일 브랜드는 아직 없어요. 다른 스타일로 찾아볼까요?".format(", ".join(tags)), None
    picked = ranked[:STYLE_TOP]
    head = "**{}** 스타일 브랜드 {}곳이에요. 요청한 스타일이 브랜드 태그에서 차지하는 비중이 큰 순서예요. 상품 줄은 옆으로 넘겨 볼 수 있어요.".format(
        " · ".join(tags), len(picked))
    if len(picked) < STYLE_MIN:
        head += " (이 스타일 브랜드가 아직 {}곳뿐이에요)".format(len(picked))
    blocks, cards = [head], []
    for i, (score, _, domain, shared) in enumerate(picked, 1):
        b = BRAND_DATA["brands"][domain]
        blocks.append(_brand_block(i, b, " · 일치도 {:.2f}".format(score), [
            "- 맞는 태그: {}".format(" · ".join(shared)),
            "- 브랜드 태그 전체: {}".format(" · ".join(b["tags"])),
        ]))
        cards.append(_brand_card(i, b, "일치도", score, shared, "브랜드 무드: " + " · ".join(b["tags"])))
    title = "{} 스타일 브랜드".format(" · ".join(tags))
    return _closing(blocks), {"type": "brands", "mode": "style", "groups": [{"title": title, "brands": cards}]}


def _unknown_brand(query):
    """DB에 없는 브랜드로 보이는 이름을 질문 앞부분에서 뽑는다 ("마뗑킴이랑 비슷한 브랜드" -> "마뗑킴")."""
    m = BRAND_NAME_RE.match(query or "")
    if not m:
        return ""
    name = re.sub(r"(?:은|는|을|를|의)$", "", m.group(1).strip())
    if not name or name in NOT_BRAND_WORDS or len(name) > 30:
        return ""
    return name


def main(query: str, class_label: str) -> dict:
    if str(class_label).strip() == STYLE_MODE:
        text, data = _style_answer(query)
        return {"result": text, "brand_request": "", "ui": ui_block(data) if data else ""}

    found = _find_brands(query)
    if not found:
        name = _unknown_brand(query)
        if name:
            # brand_request는 실행 기록(노드 출력)에 남는다. 호스트 파일로 옮기는 건 별도 스크립트가 할 일.
            return {"result": "**{}**은(는) 아직 데이터에 없는 브랜드예요. 추가 요청으로 기록해 둘게요.\n\n"
                              "대신 좋아하는 스타일(예: 빈티지, 페미닌)을 말씀해 주시면 그 스타일 브랜드를 찾아드릴게요.".format(name),
                    "brand_request": name, "ui": ""}
        names = ", ".join(b["ko"] for b in BRAND_DATA["brands"].values())
        return {"result": "어떤 브랜드와 비슷한 곳을 찾으시는지 브랜드 이름을 알려주세요.\n\n"
                          "지금 비교할 수 있는 브랜드: " + names, "brand_request": "", "ui": ""}
    blocks, groups = [], []
    for domain in found[:2]:
        brand = BRAND_DATA["brands"][domain]
        part = ["**{}** 기준으로 분위기가 비슷한 브랜드 {}곳이에요. 상품 줄은 옆으로 넘겨 볼 수 있어요.".format(
            _label(brand), len(brand["similar"]))]
        cards = []
        for i, s in enumerate(brand["similar"], 1):
            tags = " · ".join(s["common_tags"]) if s["common_tags"] else "없음"
            target = dict(BRAND_DATA["brands"].get(s["domain"], {}), ko=s["ko"], en=s["en"], url=s["url"])
            part.append(_brand_block(i, target, " · 유사도 {:.2f}".format(s["score"]), ["- 공통 태그: {}".format(tags), "- " + s["reason"]]))
            cards.append(_brand_card(i, target, "유사도", s["score"], s["common_tags"], s["reason"]))
        blocks.append("\n\n".join(part))
        groups.append({"title": "{} 기준으로 분위기가 비슷한 브랜드".format(_label(brand)), "brands": cards})
    payload = {"type": "brands", "mode": "similar", "groups": groups}
    return {"result": _closing(blocks), "brand_request": "", "ui": ui_block(payload)}
